/**
 * This is a GoToService for a listing code compare panel. It allows the goTo to occur relative to
 * the left or right listing panel of a dual listing panel, since the left and right sides can be
 * displaying totally different addresses.
 */
class ListingDisplayGoToService : GoToService {

	private ListingPanel listingPanel;

	/**
	 * Constructs a goTo service for a dual listing panel.
	 * 
	 * @param listingPanel the listing panel to be navigated to
	 */
	ListingDisplayGoToService(ListingPanel listingPanel) {
		this.listingPanel = listingPanel;
	}

	/* @Override */
	public bool goTo(ProgramLocation loc) {
		return doGoTo(loc);
	}

	/* @Override */
	public bool goTo(Navigatable navigatable, Program program, Address address,
			Address refAddress) {
		return doGoTo(new ProgramLocation(program, address));
	}

	/* @Override */
	public bool goTo(ProgramLocation loc, Program program) {
		return doGoTo(loc);
	}

	/* @Override */
	public bool goTo(Navigatable navigatable, ProgramLocation loc, Program program) {
		return doGoTo(loc);
	}

	/* @Override */
	public bool goTo(Navigatable navigatable, Address goToAddress) {
		return doGoTo(goToAddress);
	}

	/* @Override */
	public bool goTo(Address currentAddress, Address goToAddress) {
		return doGoTo(goToAddress);
	}

	/* @Override */
	public bool goTo(Address goToAddress) {
		return doGoTo(goToAddress);
	}

	/* @Override */
	public bool goTo(Address goToAddress, Program program) {
		return doGoTo(goToAddress);
	}

	/* @Override */
	public bool goToExternalLocation(ExternalLocation extLoc, bool checkNavigationOption) {
		Msg.showError(this, null, "Go To Failed!",
			"Can't naviagate to an external function from here");
		return false;
	}

	/* @Override */
	public bool goToExternalLocation(Navigatable navigatable, ExternalLocation extLoc,
			bool checkNavigationOption) {
		Msg.showError(this, null, "Go To Failed!",
			"Can't naviagate to an external function from here");
		return false;
	}

	/* @Override */
	public bool goToQuery(Address fromAddr, QueryData queryData, GoToServiceListener listener,
			TaskMonitor monitor) {
		throw new UnsupportedOperationException(
			"Go To Address or Label Query is not allowed in a dual listing view.");
	}

	/* @Override */
	public bool goToQuery(Navigatable navigatable, Address fromAddr, QueryData queryData,
			GoToServiceListener listener, TaskMonitor monitor) {
		throw new UnsupportedOperationException(
			"Go To Address or Label Query is not allowed in a dual listing view.");
	}

	/* @Override */
	public Navigatable getDefaultNavigatable() {
		return new ListingDisplayNavigator(listingPanel, this);
	}

	private bool doGoTo(Address addr) {

		// Only go if the address is in the listing's current address set.
		if (!validateAddress(addr)) {
			return false;
		}

		return listingPanel.goTo(addr);
	}

	private bool doGoTo(ProgramLocation loc) {
		if (loc == null) {
			return false;
		}

		// Only go if the location address is in the listing's current address set.
		if (!validateAddress(loc.getAddress())) {
			return false;
		}

		return listingPanel.goTo(loc);
	}

	/**
	 * Checks the address to make sure the listing won't navigate outside the addresses it currently
	 * has loaded. If it is not a valid address it will set a status message on the dual listing.
	 * 
	 * @param addr the address to check
	 * @return true if the address is valid for navigation.
	 */
	private bool validateAddress(Address addr) {
		if (addr == null) {
			return false;
		}
		AddressIndexMap map = listingPanel.getAddressIndexMap();
		AddressSetView addresses = map.getOriginalAddressSet();
		if (!addresses.contains(addr)) {
			DockingWindowManager.getActiveInstance().setStatusText("""
					"%s" is outside the current listing's view""".formatted(addr));
			return false;
		}
		return true;
	}
}
